import { DataTypes } from "sequelize";
import sequelize from "../../config/database.js";
import { EducationChapter } from "../curriculum/curriculum_schema.js";

// Node owns this table — AI Learning Decks, generated by RAGProductionApp
// always via its Celery worker (core/slide_deck_tasks.py — unlike mind
// maps, there is no synchronous variant here); it never persists a deck
// itself, the worker reports its outcome back here via
// POST /api/slide-deck/callback/:slideDeckId, mirroring
// education_mind_maps' own convention exactly, minus the `variant`
// column (one deck per generation, not 5).
//
// A chapter+board+standard scope can now hold MANY decks (a shared pool,
// mirroring EducationFlashcardSet) — see EducationSlideDeckView
// (slide_deck_view_schema.js) for the per-student history/regeneration
// model, and 20260910f_add_mind_map_slide_deck_pools.sql for the
// migration that dropped the old one-deck-per-scope unique constraint.

export const EducationSlideDeck = sequelize.define(
  "EducationSlideDeck",
  {
    slide_deck_id: {
      type: DataTypes.INTEGER,
      autoIncrement: true,
      primaryKey: true,
    },
    chapter_id: {
      type: DataTypes.INTEGER,
      allowNull: false,
      references: {
        model: EducationChapter,
        key: "chapter_id",
      },
    },
    board: {
      type: DataTypes.STRING(100),
      allowNull: false,
    },
    standard: {
      type: DataTypes.STRING(100),
      allowNull: false,
    },
    status: {
      type: DataTypes.ENUM("pending", "processing", "completed", "failed"),
      allowNull: false,
      defaultValue: "pending",
    },
    // { slides: [{ id, type, heading, subheading, key_points, explanation,
    //   steps, question, options, correct_answer,
    //   explanation_after_answer, image_required, citation, image }] }
    // — null until status is "completed".
    payload: {
      type: DataTypes.JSONB,
      allowNull: true,
    },
    error_message: {
      type: DataTypes.TEXT,
      allowNull: true,
    },
    generated_at: {
      type: DataTypes.DATE,
      allowNull: true,
    },
  },
  {
    tableName: "education_slide_decks",
    underscored: true,
    timestamps: true,
    createdAt: "created_at",
    updatedAt: "updated_at",
  }
);

EducationSlideDeck.associate = (models) => {
  EducationSlideDeck.belongsTo(models.EducationChapter, { foreignKey: "chapter_id", as: "chapter" });
};

export default EducationSlideDeck;
